 */
var anneau = [];
var NB_anneaux = 60; 

var racine_2;

var CC3, CC4;
var centre_ecran;

var DIM_base;

var BETA;								// Angle de déviation

var coef_HH, coef_TOP;	// Pour détezrmination du sommet du 1er triangle
var coef_ss, coef_ee;		// Coefs pour construction des 2 triangles "enfants"

var dim_MINI = 0.5;

var Slider_D, Slider_I;

//$$$$$$$$$$ 

function setup() {

  createCanvas(windowWidth, windowHeight);
  smooth();

  // Curseurs : Animation (Décentrage en %), Nombre d'itérations

  Slider_D = createSlider(-75, 75, -50, 1);
  Slider_D.position(50, 100);

  Slider_I = createSlider(0, 6, 3, 1);
  Slider_I.position(50, 150);

	//===

	translate(width/2, height/2);
	centre_ecran = createVector(0, 0);

	CC4 = createVector(height * 0.58, 0.0);
  CC4.rotate(QUARTER_PI);
  CC3 = CC4.copy();
  CC3.rotate(HALF_PI);

	//===

	DIM_base = p5.Vector.dist(CC3, CC4);

	racine_2 = sqrt(2);

	//=== Creation des "Objet" de la class Cluster

	for (i = 0; i < NB_anneaux; i++) {
		anneau[i] = new Cluster();
	}

}

//$$$$$$$$$$ 

function draw() {

  colorMode(HSB);
	background(200, 72, 47);
	stroke(0);

  // Curseur de déplacement du sommet du triangle de base (déviation)

	textSize(20);
	strokeWeight(1.5);

  BETA = (Slider_D.value() / 100) * (45);
  text("Animation" , Slider_D.x + Slider_D.width + 30, 110);

  //  Curseur NOMBRE D'ITERATIONS

  nb_iter = Slider_I.value();
  text("Itérations : " + nb_iter, Slider_I.x + Slider_I.width + 30, 160);

	//=== Calcul des coefficients pour le sommet "top" (par rapport à la base du triangle BM)

	coef_HH = 0.5 * (1 + racine_2 * sin(radians(BETA)));		  // Pied de la hauteur de "top" sur la base "start-end"
	coef_TOP = 0.5 * (racine_2 * cos(radians(BETA)) - 1);			// Sommet "top" du triangle de base

	//=== Calcul des coefficients pour construction des 2 triangles enfants
	//	=> coef_ss = sq(long_start / long_base);
  //	=> coef_ee = sq(long_end / long_base);

	coef_ss = sq(coef_HH) + sq(coef_TOP);		// pour calcul du sommet du triangle enfant près de start
	coef_ee = sq(1-coef_HH) + sq(coef_TOP);	// pour calcul du sommet du triangle enfant près de end

	//===

	stroke(0);
	strokeWeight(0.4);

	translate(width/2, height/2);

	for(var i = 0; i < 4; i++) {
		push();

			rotate(i%4 * HALF_PI);

			anneau[0].triangle_de_base(CC3, CC4);
			anneau[0].iterate();
			anneau[0].render();

			for (j = 1; j < NB_anneaux; j++) {

				anneau[j].triangle_de_base(anneau[j-1].M1, anneau[j-1].M2);
				anneau[j].iterate();
				anneau[j].render();
			}

		pop();
	}
}

